import React, { useState } from 'react';
import './Header.css';

function Header({ currentUser, onGoToAuth, onLogout, onNavigate }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  return (
    <header className="header">
      <div className="header-container">
        {/* Logo */}
        <div className="logo">
          <span className="logo-icon">🎬</span>
          <span className="logo-text">CinemaHub</span>
        </div>

        {/* Navigation Menu */}
        <nav className={`nav-menu ${mobileMenuOpen ? 'active' : ''}`}>
          <a href="#home" className="nav-link active">Trang Chủ</a>
          <a href="#movies" className="nav-link">Phim</a>
          <a href="#genres" className="nav-link">Thể Loại</a>
          <a href="#deals" className="nav-link">Khuyến Mãi</a>
          <a href="#contact" className="nav-link">Liên Hệ</a>
        </nav>

        {/* User Section */}
        <div className="user-section">
          {currentUser ? (
            <div className="user-menu">
              <div className="user-info">
                <span className="user-avatar">👤</span>
                <span className="user-name">{currentUser.username}</span>
              </div>
              <button 
                className="logout-btn"
                onClick={onLogout}
              >
                Đăng Xuất
              </button>
            </div>
          ) : (
            <button 
              className="login-btn"
              onClick={onGoToAuth}
            >
              Đăng Nhập
            </button>
          )}
        </div>

        {/* Mobile Menu Toggle */}
        <button 
          className="mobile-menu-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
          <span></span>
          <span></span>
          <span></span>
        </button>
      </div>
    </header>
  );
}

export default Header;
